    // Optimized schedule
    //
    // Goal:
    //   - Preserve original math and row/column semantics.
    //   - Exploit data locality by traversing the x-dimension (j or l)
    //     as the innermost loop wherever possible.
    //   - Use parallelism over the outer (row) dimension.
    //   - Vectorize the innermost dimension for better SIMD utilization.
    //
    // Note:
    //   For each reduction, we reorder loops so that the reduction
    //   variable (k / r*) stays outside the vectorized x-dimension.
    //   This preserves the per-element reduction order over k while
    //   enabling dense vector loads/stores in the x direction.
    // --------------------------------------------------------------------

    const int vec_width = 8;  // reasonable default SIMD width for modern x86

    // Schedule for E = A * B  (E(j, i) ~ E[i][j])
    //   Outer parallel over i (rows)
    //   Inner vectorized over j (columns)
    E.compute_root()
     .reorder(j, i)           // i outer, j inner (x-fastest)
     .parallel(i)
     .vectorize(j, vec_width);

    // Reduction update:
    //   Order loops as: for i (parallel), for rAB (k), for j (vectorized)
    //   This keeps the k-reduction in the same order per element as the
    //   original C code (k increases from 0..nk-1 for each (i,j)), but
    //   allows us to process multiple j's at once.
    E.update()
     .reorder(j, rAB, i)      // loop nest: i (outer), rAB, j (inner)
     .parallel(i)
     .vectorize(j, vec_width);

    // Schedule for F = C * D  (F(l, j) ~ F[j][l])
    //   Parallel over j (rows in original C)
    //   Vectorize over l (columns)
    F.compute_root()
     .reorder(l, j)           // j outer, l inner
     .parallel(j)
     .vectorize(l, vec_width);

    F.update()
     .reorder(l, rCD, j)      // loop nest: j (outer), rCD, l (inner)
     .parallel(j)
     .vectorize(l, vec_width);

    // Schedule for G = E * F  (G_func(l, i) ~ G[i][l])
    //   Parallel over i (rows)
    //   Vectorize over l (columns)
    G_func.compute_root()
          .reorder(l, i)      // i outer, l inner
          .parallel(i)
          .vectorize(l, vec_width);

    G_func.update()
          .reorder(l, rEF, i) // loop nest: i (outer), rEF, l (inner)
          .parallel(i)
          .vectorize(l, vec_width);

    // Compile the kernel to machine code.
    G_func.compile_jit();

    // Measure execution time (kernel only).
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: realize G_func into Buffer G (shape nl x ni).
    G_func.realize(G);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result matrix G to stderr.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < ni; ii++) {
            for (int jj = 0; jj < nl; jj++) {
                // G[ii][jj] in C => G(jj, ii) in Halide
                std::cerr << G(jj, ii) << '\n';
            }
        }
    }

    // Print timing in seconds to stdout with 6 decimal places,
    // matching the style of the gemm.cpp example.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
