    //     for k in [0, nm):             // rCD
    //       for l in [0, nl):           // vectorized
    //         F(j,l) += C(j,k) * D(k,l)
    //
    // Written in our coordinates F(l,j), this is:
    //   for j: for rCD: for l:
    // Memory:
    //   - C_param(rCD, j): contiguous in rCD
    //   - D_param(l, rCD): contiguous in l
    //   - F(l, j): contiguous in l
    {
        Var lo("lo_F"), li("li_F");

        // Pure definition: initialize F(l,j) = 0
        F.compute_root()
         .split(l, lo, li, vec)       // l = lo*vec + li
         .reorder(li, lo, j)
         .parallel(j)
         .vectorize(li);

        // Update (reduction) definition
        F.update()
         .split(l, lo, li, vec)
         // inner loops: li (vectorized), lo, then rCD, outermost j
         // -> for j: for rCD: for lo: for li
         .reorder(li, lo, rCD, j)
         .parallel(j)
         .vectorize(li);
    }

    // ------------------
    // Schedule for G = E * F
    // ------------------
    //
    // Desired loop structure for the update:
    //   for i in [0, ni):               // parallel
    //     for k in [0, nj):             // rEF
    //       for l in [0, nl):           // vectorized
    //         G(i,l) += E(i,k) * F(k,l)
    //
    // In our coordinates G_func(l,i):
    //   for i: for rEF: for l:
    // Memory:
    //   - E(rEF, i): reused across all l for given (i,rEF)
    //   - F(l, rEF): contiguous in l
    //   - G_func(l, i): contiguous in l
    {
        Var lo("lo_G"), li("li_G");

        // Pure definition: initialize G(l,i) = 0
        G_func.compute_root()
              .split(l, lo, li, vec)
              .reorder(li, lo, i)
              .parallel(i)
              .vectorize(li);

        // Update (reduction) definition
        G_func.update()
              .split(l, lo, li, vec)
              // inner loops: li (vectorized), lo, then rEF, outermost i
              // -> for i: for rEF: for lo: for li
              .reorder(li, lo, rEF, i)
              .parallel(i)
              .vectorize(li);
    }

    // Compile the kernel to machine code (for the chosen target).
    G_func.compile_jit(target);

    // Measure execution time (kernel only).
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: realize G_func into Buffer G (shape nl x ni).
    G_func.realize(G);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result matrix G to stderr.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < ni; ii++) {
            for (int jj = 0; jj < nl; jj++) {
                // G[ii][jj] in C => G(jj, ii) in Halide
                std::cerr << G(jj, ii) << '\n';
            }
        }
    }

    // Print timing in seconds to stdout with 6 decimal places,
    // matching the style of the gemm.cpp example.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
